-- Snowflake governance metadata for utilities-meter-to-cash (review; applying is A2, policies are A3)

CREATE TAG IF NOT EXISTS ACME_CUSTOMER_GOLD.CLASSIFICATION ALLOWED_VALUES 'public','internal','confidential','restricted';
CREATE MASKING POLICY IF NOT EXISTS ACME_CUSTOMER_GOLD.MASK_RESTRICTED AS (v VARCHAR) RETURNS VARCHAR ->
  CASE WHEN IS_ROLE_IN_SESSION('RESTRICTED_READER') THEN v ELSE '***MASKED***' END;

COMMENT ON TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT IS 'Billing account of a customer';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT MODIFY COLUMN CUSTOMER_ACCOUNT_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT MODIFY COLUMN ACCOUNT_STATUS SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT MODIFY COLUMN RATE_CLASS SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT MODIFY COLUMN CUSTOMER_NAME SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'restricted';
-- ALTER TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT MODIFY COLUMN CUSTOMER_NAME SET MASKING POLICY ACME_CUSTOMER_GOLD.MASK_RESTRICTED;
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_CUSTOMER_ACCOUNT MODIFY COLUMN OPEN_DATE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';

COMMENT ON TABLE ACME_CUSTOMER_GOLD.DIM_PREMISE IS 'Service location';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_PREMISE MODIFY COLUMN PREMISE_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_PREMISE MODIFY COLUMN CUSTOMER_ACCOUNT_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_PREMISE MODIFY COLUMN PREMISE_TYPE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_PREMISE MODIFY COLUMN REGION_CODE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';

COMMENT ON TABLE ACME_CUSTOMER_GOLD.DIM_METER IS 'Installed meter';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_METER MODIFY COLUMN METER_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_METER MODIFY COLUMN PREMISE_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_METER MODIFY COLUMN METER_TYPE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.DIM_METER MODIFY COLUMN INSTALL_DATE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';

COMMENT ON TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION IS 'Billed versus metered consumption per bill';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN BILL_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN CUSTOMER_ACCOUNT_ID SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN BILL_PERIOD_START SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN BILL_PERIOD_END SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN BILLED_KWH SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN METERED_KWH SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN ESTIMATED_READ_SHARE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN VARIANCE_KWH SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
ALTER TABLE ACME_CUSTOMER_GOLD.FCT_BILLED_CONSUMPTION MODIFY COLUMN AMOUNT_DUE SET TAG ACME_CUSTOMER_GOLD.CLASSIFICATION = 'internal';
